import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import kotlin.system.measureTimeMillis

// 模拟"生产快、消费慢"的数据源（如行情推送、传感器）
fun priceStream(): Flow<Long> = flow {
    var price = 100L
    repeat(10) { i ->
        delay(50)                       // 生产端：每 50ms 发射一条
        price += i
        println("  [produce] #$i price=$price  (${Thread.currentThread().name})")
        emit(price)
    }
}.flowOn(Dispatchers.Default)            // 上游切到 Default，与下游并行执行

suspend fun consumeSlowly(price: Long) {
    delay(150)                           // 消费端：每条需 150ms
    println("  [consume] $price")
}

fun main() = runBlocking {

    println("=== 1. 默认：串行，生产被消费完全拖慢 ===")
    val t1 = measureTimeMillis {
        priceStream().collect { consumeSlowly(it) }
    }
    println("耗时: ${t1}ms (约 2000ms)\n")

    println("=== 2. buffer(3)：异步化 + 缓冲，不丢数据 ===")
    val t2 = measureTimeMillis {
        priceStream().buffer(3).collect { consumeSlowly(it) }
    }
    println("耗时: ${t2}ms (显著缩短，全部数据都被处理)\n")

    println("=== 3. conflate()：只保留最新值，中间值被丢弃 ===")
    val t3 = measureTimeMillis {
        priceStream().conflate().collect { consumeSlowly(it) }
    }
    println("耗时: ${t3}ms (最快，但只看到少数几个值)\n")

    println("=== 4. collectLatest()：新值一到就取消旧处理 ===")
    val t4 = measureTimeMillis {
        priceStream().collectLatest { price ->
            delay(150)
            println("  [consume] $price")   // 多数处理会被取消，只有最后一次真正完成
        }
    }
    println("耗时: ${t4}ms\n")

    println("=== 5. 热流：StateFlow / SharedFlow ===")
    val state = MutableStateFlow(100L)                      // 天然 conflate，永远持有"当前值"
    val events = MutableSharedFlow<String>(replay = 1, extraBufferCapacity = 8)

    val job = launch {
        state.collect { println("  [state] latest = $it") }
    }
    events.tryEmit("boot")                                  // replay=1：订阅前发射也能收到

    repeat(5) { i ->
        state.value = 100L + i                              // 非挂起更新，立即生效
        events.tryEmit("tick-$i")
        delay(30)
    }
    job.cancel()

    // 新订阅者可通过 replay 拿到最近一条事件
    println("  [events] replay 得到: ${events.first()}")
}

